def comps(mask):
    seen=set(); res=[]
    for cell in mask:
        if cell in seen: continue
        q=deque([cell]); seen.add(cell); comp=[]
        while q:
            r,c=q.popleft(); comp.append((r,c))
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                n=(r+dr,c+dc)
                if n in mask and n not in seen:
                    seen.add(n); q.append(n)
        res.append(comp)
    return res
